def _update_legend_data(self, ax):
        """Extract the legend data from an axes object and save it."""
        # Build initial context (equivalent to _build_legend_context)
        context = {
            "ax": ax,
            "data": {},
            "extract_handles": self._extract_legend_handles,
            "clear_legend": True,
        }

        # Stage 1: Extract (priority 10) - Extract handles from legend object
        if (ax.legend_ is not None and 
            context.get("extract_handles", False)):
            handles = get_legend_handles(ax.legend_)
            labels = [t.get_text() for t in ax.legend_.texts]
            context["data"].update(
                {label: handle for handle, label in zip(handles, labels)}
            )

        # Stage 2: Collect (priority 20) - Collect labeled artists from axes
        handles, labels = ax.get_legend_handles_labels()
        context["data"].update(
            {label: handle for handle, label in zip(handles, labels)}
        )

        # Stage 3: Normalize (priority 30) - Ensure consistent label typing
        data = context.get("data", {})
        normalized = {}
        for label, handle in data.items():
            if isinstance(label, str):
                normalized[label] = handle
            else:
                normalized[str(label)] = handle
        context["data"] = normalized

        # Stage 4: Order (priority 40) - Preserve categorical ordering
        data = context.get("data", {})
        if data:
            context["data"] = dict(data)

        # Stage 5: Cleanup (priority 80) - Handle distribution-specific legend state
        if ax.legend_ is not None:
            context.setdefault("clear_legend", True)

        # Stage 6: Finalize (priority 90) - Deduplicate legend handles
        data = context.get("data", {})
        seen_labels = set()
        deduped = {}
        for label, handle in reversed(list(data.items())):
            if label not in seen_labels:
                deduped[label] = handle
                seen_labels.add(label)
        context["data"] = dict(reversed(list(deduped.items())))

        # Update the legend data and clear if needed
        self._legend_data.update(context["data"])

        if context.get("clear_legend", True):
            ax.legend_ = None
